// Hand-written `express` stub for the flowatlas fixture suite.
//
// What `@types/express` declares for a request and a response, as far as this
// fixture writes it: four type parameters on the request - path params, the
// answer, the body and the query - that default to a dictionary or `any`, and
// one on the response, which `json` and `send` are held to. The verb methods
// take the same four, so a route can say what it reads where it is declared.

export type NextFunction = (error?: unknown) => void;

export interface ParamsDictionary {
  [key: string]: string;
}

export interface ParsedQs {
  [key: string]: undefined | string | string[] | ParsedQs | ParsedQs[];
}

export interface IncomingHttpHeaders {
  host?: string;
  'content-type'?: string;
  [header: string]: string | string[] | undefined;
}

export interface Request<P = ParamsDictionary, ResBody = any, ReqBody = any, ReqQuery = ParsedQs> {
  params: P;
  query: ReqQuery;
  body: ReqBody;
  headers: IncomingHttpHeaders;
}

export interface Response<ResBody = any> {
  status(code: number): this;
  json(body?: ResBody): this;
  send(body?: ResBody): this;
  sendStatus(code: number): this;
}

export type RequestHandler<P = ParamsDictionary, ResBody = any, ReqBody = any, ReqQuery = ParsedQs> = (
  req: Request<P, ResBody, ReqBody, ReqQuery>,
  res: Response<ResBody>,
  next: NextFunction,
) => unknown;

type Verb = <P = ParamsDictionary, ResBody = any, ReqBody = any, ReqQuery = ParsedQs>(
  path: string,
  ...handlers: Array<RequestHandler<P, ResBody, ReqBody, ReqQuery>>
) => IRouter;

export interface IRouter {
  get: Verb;
  post: Verb;
  put: Verb;
  patch: Verb;
  delete: Verb;
  use(...handlers: Array<RequestHandler | IRouter>): this;
  use(path: string, ...handlers: Array<RequestHandler | IRouter>): this;
}

export interface Router extends IRouter {}

export interface Application extends IRouter {
  listen(port: number, callback?: () => void): unknown;
}

export interface Express extends Application {}

export declare function Router(): Router;

declare function express(): Express;

declare namespace express {
  function json(): RequestHandler;
}

export default express;
